import sys

COLUMNS = 5
CREDIT_TYPES = ("charge",)
DEBIT_TYPES = ("refund",)


def parse_events(path):
    events = []
    with open(path) as handle:
        for raw in handle:
            line = raw.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            parts = [part.strip() for part in line.split(",")]
            if len(parts) != COLUMNS:
                continue
            event_id, event_type, merchant, amount, received_at = parts
            if not event_id or not merchant:
                continue
            try:
                amount_cents = int(amount)
            except ValueError:
                continue
            events.append(
                {
                    "event_id": event_id,
                    "type": event_type,
                    "merchant": merchant,
                    "amount": amount_cents,
                    "received_at": received_at,
                }
            )
    return events


def in_arrival_order(events):
    return sorted(events, key=lambda event: event["received_at"])


def dedupe(events):
    seen = set()
    unique = []
    for event in events:
        key = (event["merchant"], event["type"], event["amount"])
        if key in seen:
            continue
        seen.add(key)
        unique.append(event)
    return unique


def compute_balances(events):
    balances = {}
    for event in events:
        merchant = event["merchant"]
        if event["type"] in CREDIT_TYPES:
            balances[merchant] = balances.get(merchant, 0) + event["amount"]
        elif event["type"] in DEBIT_TYPES:
            balances[merchant] = balances.get(merchant, 0) - event["amount"]
    return balances


def main():
    events = parse_events(sys.argv[1])
    ordered = in_arrival_order(events)
    unique = dedupe(ordered)
    balances = compute_balances(unique)
    print("=== Net balance (cents) by merchant ===")
    for merchant in sorted(balances):
        print(merchant + ": " + str(balances[merchant]))


if __name__ == "__main__":
    main()

"""Resolve duplicate ontology entities and count links per entity.

The ontology reconciliation job reads the link feed emitted by the resolver and
reports, for each entity, how many distinct links resolved to it. The registry
team reads this every morning to confirm the reconciliation run did not drop or
double-assign links. Duplicate entity records and redelivered links are part of
normal input; see task.md for the column layout and the delivery contract the
feed is allowed to violate.
"""

import sys

REGISTERED_NAMESPACES = ("commercial", "gov")


def normalize_name(raw):
    """Entity names are case-insensitive and may carry incidental whitespace,
    so fold them to a canonical form before comparing."""
    return raw.strip().lower()


def parse_line(raw):
    """Turn one feed line into a link record, or None when the line is a
    comment, malformed, or targets an unregistered namespace."""
    line = raw.rstrip("\n")
    if not line or line.startswith("#"):
        return None
    parts = line.split(",")
    if len(parts) != 3:
        return None
    namespace, name, link_id = (part.strip() for part in parts)
    if namespace not in REGISTERED_NAMESPACES:
        return None
    if name == "" or link_id == "":
        return None
    return {
        "namespace": namespace,
        "name": normalize_name(name),
        "link_id": link_id,
    }


def parse_links(path):
    """Read the feed and keep only well-formed link records."""
    records = []
    with open(path) as handle:
        for raw in handle:
            record = parse_line(raw)
            if record is not None:
                records.append(record)
    return records


def dedupe_links(records):
    """Drop redeliveries: the bus is at-least-once, so the same link_id can
    arrive more than once. Keep the first occurrence of each link_id."""
    seen = set()
    unique = []
    for record in records:
        if record["link_id"] in seen:
            continue
        seen.add(record["link_id"])
        unique.append(record)
    return unique


def entity_key(namespace, name):
    """The identity that decides whether two records describe one entity and so
    should have their links merged into a single count."""
    return name


def count_links(records):
    """Count how many links resolved to each entity identity."""
    counts = {}
    for record in records:
        key = entity_key(record["namespace"], record["name"])
        counts[key] = counts.get(key, 0) + 1
    return counts


def distinct_entities(records):
    """Every (namespace, name) entity seen in the feed, ordered by name then
    namespace so entities that share a name are listed together."""
    entities = {}
    for record in records:
        entities[(record["namespace"], record["name"])] = True
    return sorted(entities, key=lambda pair: (pair[1], pair[0]))


def format_row(namespace, name, total):
    """One report line: the entity's full path and its link count."""
    return namespace + "/" + name + ": " + str(total)


def print_report(records):
    counts = count_links(records)
    print("=== Links resolved per entity ===")
    for namespace, name in distinct_entities(records):
        total = counts[entity_key(namespace, name)]
        print(format_row(namespace, name, total))


def main():
    records = dedupe_links(parse_links(sys.argv[1]))
    print_report(records)


if __name__ == "__main__":
    main()

"""Roll raw metric samples into fixed 60-second windows.

The on-call SRE reads the per-window count and sum for one metric to decide
whether the current minute breached an alert threshold. Input is the
comma-separated feed emitted by the collector agents; see task.md for the
column layout and the delivery contract the feed is allowed to violate.
"""

import calendar
import sys
import time

WINDOW_SECONDS = 60
TARGET_METRIC = "web.5xx"
TIMESTAMP_FORMAT = "%Y-%m-%dT%H:%M:%SZ"


def parse_line(raw, metric):
    """Turn one feed line into a sample dict, or None if it is not a usable
    sample for this metric (comment, malformed, or a different metric)."""
    line = raw.rstrip("\n")
    if not line or line.startswith("#"):
        return None
    parts = line.split(",")
    if len(parts) != 4:
        return None
    ts_text, metric_name, sample_id, value = (part.strip() for part in parts)
    if metric_name != metric:
        return None
    if value == "":
        return None
    try:
        value_num = int(value)
    except ValueError:
        return None
    try:
        epoch = calendar.timegm(time.strptime(ts_text, TIMESTAMP_FORMAT))
    except ValueError:
        return None
    return {
        "ts_text": ts_text,
        "epoch": epoch,
        "sample_id": sample_id,
        "value": value_num,
    }


def parse_samples(path, metric):
    """Read the feed and keep only well-formed samples for `metric`."""
    samples = []
    with open(path) as handle:
        for raw in handle:
            sample = parse_line(raw, metric)
            if sample is not None:
                samples.append(sample)
    return samples


def dedupe(samples):
    """Drop redeliveries: the bus is at-least-once, so the same sample_id can
    arrive more than once. Keep the first occurrence of each sample_id."""
    seen = set()
    unique = []
    for sample in samples:
        if sample["sample_id"] in seen:
            continue
        seen.add(sample["sample_id"])
        unique.append(sample)
    return unique


def window_start(epoch):
    """Return the epoch second at which `epoch`'s 60-second window begins."""
    return epoch - (epoch % WINDOW_SECONDS)


def window_starts(samples):
    """Every window start from the first sample's window through the last."""
    first = window_start(samples[0]["epoch"])
    last = window_start(samples[-1]["epoch"])
    return list(range(first, last + WINDOW_SECONDS, WINDOW_SECONDS))


def rollup(samples):
    """Aggregate samples into (window_start, count, sum) rows, oldest first."""
    if not samples:
        return []
    ordered = dedupe(samples)
    ordered.sort(key=lambda sample: sample["ts_text"])
    rows = []
    for start in window_starts(ordered):
        end = start + WINDOW_SECONDS
        in_window = [s for s in ordered if start <= s["epoch"] <= end]
        total = sum(sample["value"] for sample in in_window)
        rows.append((start, len(in_window), total))
    return rows


def format_label(start):
    """Human-readable UTC clock time for a window start."""
    return time.strftime("%H:%M:%S", time.gmtime(start))


def print_rollup(metric, samples):
    print("=== " + metric + " per 60s window ===")
    for start, count, total in rollup(samples):
        print(format_label(start) + "  count=" + str(count) + "  sum=" + str(total))


def main():
    path = sys.argv[1]
    print_rollup(TARGET_METRIC, parse_samples(path, TARGET_METRIC))


if __name__ == "__main__":
    main()

"""Count click sessions per user from a raw event feed.

The Growth analyst reads the per-user session count each morning to see how many
distinct visits each user made overnight. Two consecutive clicks by the same user
belong to the same session when the gap between them is short enough; a longer gap
starts a new session. Input is the comma-separated event feed the collector writes;
see task.md for the column layout and the delivery contract the feed may violate.
"""

import calendar
import sys
import time

GAP_SECONDS = 1800
TIMESTAMP_FORMAT = "%Y-%m-%dT%H:%M:%SZ"
FIELD_COUNT = 4


def parse_line(raw):
    """Turn one feed line into an event dict, or None if it is not a usable
    event (a comment line or a malformed line)."""
    line = raw.rstrip("\n")
    if not line or line.startswith("#"):
        return None
    parts = line.split(",")
    if len(parts) != FIELD_COUNT:
        return None
    ts_text, user_id, event_id, platform = (part.strip() for part in parts)
    if not user_id or not event_id:
        return None
    try:
        epoch = calendar.timegm(time.strptime(ts_text, TIMESTAMP_FORMAT))
    except ValueError:
        return None
    return {
        "ts_text": ts_text,
        "epoch": epoch,
        "user_id": user_id,
        "event_id": event_id,
        "platform": platform,
    }


def read_events(path):
    """Read the feed and keep only well-formed events, in arrival order."""
    events = []
    with open(path) as handle:
        for raw in handle:
            event = parse_line(raw)
            if event is not None:
                events.append(event)
    return events


def dedupe(events):
    """Drop redeliveries: the bus is at-least-once, so the same event_id can
    arrive more than once. Keep the first occurrence of each event_id."""
    seen = set()
    unique = []
    for event in events:
        if event["event_id"] in seen:
            continue
        seen.add(event["event_id"])
        unique.append(event)
    return unique


def group_by_user(events):
    """Bucket events under each user_id, keeping first-seen user order."""
    grouped = {}
    for event in events:
        user_id = event["user_id"]
        if user_id not in grouped:
            grouped[user_id] = []
        grouped[user_id].append(event)
    return grouped


def count_sessions(user_events):
    """Count inactivity-gap sessions for one user's events; the events are
    ordered by timestamp first, then each gap that breaks the inactivity window
    opens a new session."""
    ordered = sorted(user_events, key=lambda event: event["ts_text"])
    sessions = 0
    previous_epoch = None
    for event in ordered:
        if previous_epoch is None:
            sessions += 1
        elif event["epoch"] - previous_epoch >= GAP_SECONDS:
            sessions += 1
        previous_epoch = event["epoch"]
    return sessions


def build_counts(events):
    """Map each user_id to its session count."""
    grouped = group_by_user(dedupe(events))
    counts = {}
    for user_id in grouped:
        counts[user_id] = count_sessions(grouped[user_id])
    return counts


def print_counts(events):
    """Print each user's session count, users in sorted order."""
    print("=== sessions per user (gap " + str(GAP_SECONDS) + "s) ===")
    counts = build_counts(events)
    for user_id in sorted(counts):
        print(user_id + ": " + str(counts[user_id]))


def main():
    path = sys.argv[1]
    print_counts(read_events(path))


if __name__ == "__main__":
    main()

"""Nightly reliability rollup.

Reads an application log feed and reports, for each service, how many
ERROR lines it emitted during the window. The on-call engineer reads this
every morning to decide which services to follow up on.

Field layout per line: timestamp service level message
"""

import sys

ERROR_LEVEL = "ERROR"
FIELD_COUNT = 4


def parse_line(raw):
    """Return {service, level} for a usable line, or None to skip it."""
    line = raw.rstrip("\n")
    if not line or line.startswith("#"):
        return None
    parts = line.split(None, FIELD_COUNT - 1)
    if len(parts) < FIELD_COUNT:
        return None
    timestamp, service, level, message = parts
    return {
        "service": service,
        "level": level.strip().upper(),
    }


def read_events(path):
    """Load every usable line from the feed in arrival order."""
    events = []
    with open(path) as handle:
        for raw in handle:
            event = parse_line(raw)
            if event is not None:
                events.append(event)
    return events


def group_by_service(events):
    """Bucket levels under each service, keeping first-seen order."""
    grouped = {}
    for event in events:
        service = event["service"]
        if service not in grouped:
            grouped[service] = []
        grouped[service].append(event["level"])
    return grouped


def build_report(grouped):
    """Count ERROR lines for each service."""
    report = {}
    error_count = 0
    for service in grouped:
        for level in grouped[service]:
            if level == ERROR_LEVEL:
                error_count += 1
        report[service] = error_count
    return report


def main():
    events = read_events(sys.argv[1])
    grouped = group_by_service(events)
    report = build_report(grouped)
    print("=== ERROR lines by service ===")
    for service in report:
        print(service + ": " + str(report[service]))


if __name__ == "__main__":
    main()

"""Evaluate each monitored series against its threshold for one window.

On-call reads this status board during an incident: for every monitored series
it reports whether the window average breached the alert threshold. See task.md
for the column layout and the delivery contract the feed may violate.
"""

import calendar
import sys
import time

TIMESTAMP_FORMAT = "%Y-%m-%dT%H:%M:%SZ"
WINDOW_START = "2026-05-01T12:00:00Z"
WINDOW_END = "2026-05-01T12:05:00Z"


def to_epoch(ts_text):
    return calendar.timegm(time.strptime(ts_text, TIMESTAMP_FORMAT))


def parse_feed(path):
    """Read the feed into monitor thresholds and in-window samples."""
    monitors = {}
    samples = []
    window_start = to_epoch(WINDOW_START)
    window_end = to_epoch(WINDOW_END)
    with open(path) as handle:
        for raw in handle:
            line = raw.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            parts = [part.strip() for part in line.split(",")]
            if parts[0] == "monitor" and len(parts) == 4:
                try:
                    monitors[parts[1]] = {"crit": int(parts[2]), "warn": int(parts[3])}
                except ValueError:
                    continue
            elif parts[0] == "sample" and len(parts) == 5:
                try:
                    epoch = to_epoch(parts[3])
                    value = int(parts[4])
                except ValueError:
                    continue
                if window_start <= epoch < window_end:
                    samples.append({"series": parts[1], "sample_id": parts[2], "value": value})
    return monitors, samples


def group_values(samples):
    """Map each series to its in-window values, dropping at-least-once
    redeliveries by sample_id."""
    seen = set()
    by_series = {}
    for sample in samples:
        if sample["sample_id"] in seen:
            continue
        seen.add(sample["sample_id"])
        by_series.setdefault(sample["series"], []).append(sample["value"])
    return by_series


def evaluate(values, monitor):
    """Return the status for one series' window values against its monitor."""
    average = sum(values) / len(values) if values else 0
    if average >= monitor["crit"]:
        return "ALERT"
    return "OK"


def main():
    monitors, samples = parse_feed(sys.argv[1])
    by_series = group_values(samples)
    print("=== Monitor status ===")
    for series in sorted(monitors):
        print(series + ": " + evaluate(by_series.get(series, []), monitors[series]))


if __name__ == "__main__":
    main()

"""Overnight cache eviction report.

Replays the day's cache write log, runs the eviction sweep at a fixed
checkpoint, and prints how many entries are still live in each namespace.
The capacity-planning on-call reads this report every morning to decide how
much memory each namespace needs, so the per-namespace counts have to line up
with the cache's own metrics endpoint.

Log columns (comma-separated): namespace,key,expires_at[,pinned]
An entry is expired when its expires_at is at or before the checkpoint NOW.
"""

import sys

NOW = 1700000000
MIN_FIELDS = 3
MAX_FIELDS = 4
PINNED_FLAG = "pinned"


def parse_line(raw):
    """Return an entry dict for a usable log line, or None to skip it."""
    line = raw.rstrip("\n")
    if not line or line.startswith("#"):
        return None
    parts = [part.strip() for part in line.split(",")]
    if len(parts) < MIN_FIELDS or len(parts) > MAX_FIELDS:
        return None
    namespace, key, expires_at = parts[0], parts[1], parts[2]
    try:
        expires_value = int(expires_at)
    except ValueError:
        return None
    pinned = len(parts) == MAX_FIELDS and parts[3] == PINNED_FLAG
    return {
        "namespace": namespace,
        "key": key,
        "expires_at": expires_value,
        "pinned": pinned,
    }


def read_events(path):
    """Load every usable write from the log in arrival order."""
    events = []
    with open(path) as handle:
        for raw in handle:
            event = parse_line(raw)
            if event is not None:
                events.append(event)
    return events


def build_cache(events):
    """Fold writes into per-namespace entries.

    A later write to the same namespace and key refreshes that entry in
    place, so the most recent expiry wins and the entry keeps its slot.
    """
    cache = {}
    for event in events:
        namespace = event["namespace"]
        if namespace not in cache:
            cache[namespace] = {}
        cache[namespace][event["key"]] = event
    return cache


def evict_expired(entries, now):
    """Drop the entries whose expiry is at or before now, in place."""
    index = 0
    while index < len(entries):
        entry = entries[index]
        if entry["expires_at"] <= now:
            entries.pop(index)
        index += 1
    return entries


def count_live(cache, now):
    """Report how many entries survive the sweep in each namespace."""
    report = {}
    for namespace in cache:
        entries = list(cache[namespace].values())
        survivors = evict_expired(entries, now)
        report[namespace] = len(survivors)
    return report


def format_report(report):
    """Render the report with namespaces in sorted order."""
    lines = ["=== Live entries by namespace ==="]
    for namespace in sorted(report):
        lines.append(namespace + ": " + str(report[namespace]))
    return "\n".join(lines)


def main():
    events = read_events(sys.argv[1])
    cache = build_cache(events)
    report = count_live(cache, NOW)
    print(format_report(report))


if __name__ == "__main__":
    main()

import sys

VALID_STREAMS = ("primary", "backup")


def parse_events(path):
    events = []
    with open(path) as handle:
        for raw in handle:
            line = raw.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            parts = line.split(",")
            if len(parts) != 4:
                continue
            stream, account_id, event_id, seconds = (part.strip() for part in parts)
            if stream not in VALID_STREAMS:
                continue
            if seconds == "":
                continue
            try:
                seconds_value = int(seconds)
            except ValueError:
                continue
            events.append(
                {
                    "stream": stream,
                    "account_id": account_id.lower(),
                    "event_id": event_id,
                    "seconds": seconds_value,
                }
            )
    return events


def dedupe(events):
    seen = set()
    unique = []
    for event in events:
        if event["event_id"] in seen:
            continue
        seen.add(event["event_id"])
        unique.append(event)
    return unique


def rollup(events):
    totals = {}
    primary = dedupe([event for event in events if event["stream"] == "primary"])
    backup = dedupe([event for event in events if event["stream"] == "backup"])
    for event in primary + backup:
        totals[event["account_id"]] = totals.get(event["account_id"], 0) + event["seconds"]
    return totals


def main():
    events = parse_events(sys.argv[1])
    totals = rollup(events)
    print("=== Compute-seconds by account ===")
    for account_id in sorted(totals):
        print(account_id + ": " + str(totals[account_id]))


if __name__ == "__main__":
    main()
